		noarr::vector<'k'>() ^
		noarr::set_length<'k'>(n);

	// outer loop over k (we will skip k == 0 inside)
	traverser(k_struct).for_each([&](auto k_state) {
		std::size_t k = noarr::get_index<'k'>(k_state);

		// original C loop starts from k = 1
		if (k == 0)
			return;

		beta = (static_cast<num_t>(1.0) - alpha * alpha) * beta;
		sum = static_cast<num_t>(0.0);

		// sum = sum_{i=0}^{k-1} r[k-i-1] * y[i];
		traverser(y)
			.order(noarr::slice<'i'>(0, k))
			.for_each([&](auto i_state) {
