/**
 * Main computational kernel.
 *
 * Original C reference:
 *
 *   y[0] = -r[0];
 *   beta = 1.0;
 *   alpha = -r[0];
 *
 *   for (k = 1; k < n; k++) {
 *     beta = (1 - alpha*alpha) * beta;
 *     sum = 0;
 *     for (i = 0; i < k; i++)
 *       sum += r[k-i-1] * y[i];
 *     alpha = -(r[k] + sum) / beta;
 *
 *     for (i = 0; i < k; i++)
 *       z[i] = y[i] + alpha * y[k-i-1];
 *     for (i = 0; i < k; i++)
 *       y[i] = z[i];
 *     y[k] = alpha;
 *   }
 */
[[gnu::flatten, gnu::noinline]]
void kernel_durbin(std::size_t n, auto r, auto y) {
	using namespace noarr;

	// temporary array z[0..n-1]
	auto z = noarr::make_bag(noarr::scalar<num_t>() ^ i_vec ^ noarr::set_length<'i'>(n));

	num_t alpha;
	num_t beta;
	num_t sum;

	// Initial conditions
	y[noarr::idx<'i'>(0)] = -r[noarr::idx<'i'>(0)];
	beta = static_cast<num_t>(1.0);
	alpha = -r[noarr::idx<'i'>(0)];

	// Outer loop over k = 1 .. n-1 implemented via a traverser over a dummy k-dimension
	// We traverse k_index in [0, n-1); actual k = k_index + 1
	auto k_struct = noarr::scalar<char>() ^ noarr::vector<'k'>() ^ noarr::set_length<'k'>(n > 0 ? n - 1 : 0);

	noarr::traverser(k_struct).for_each([&](auto k_state) {
		std::size_t k = noarr::get_index<'k'>(k_state) + 1; // matches original k starting at 1

		// beta = (1 - alpha*alpha) * beta;
		beta = (static_cast<num_t>(1.0) - alpha * alpha) * beta;

		// sum = 0; for i = 0 .. k-1: sum += r[k-i-1] * y[i];
		sum = static_cast<num_t>(0.0);

		auto i_struct = noarr::scalar<char>() ^ i_vec ^ noarr::set_length<'i'>(k);

		noarr::traverser(i_struct).for_each([&](auto i_state) {
			std::size_t i = noarr::get_index<'i'>(i_state);

			sum += r[noarr::idx<'i'>(k - i - 1)] * y[i_state];
		});

		// alpha = -(r[k] + sum) / beta;
		alpha = -(r[noarr::idx<'i'>(k)] + sum) / beta;

		// for i = 0 .. k-1: z[i] = y[i] + alpha * y[k-i-1];
		noarr::traverser(i_struct).for_each([&](auto i_state) {
			std::size_t i = noarr::get_index<'i'>(i_state);

			z[i_state] = y[i_state] + alpha * y[noarr::idx<'i'>(k - i - 1)];
		});

